mapper.select:
SELECT h.FACILITY_TYPE AS facilityType, h.BRANCH_NM AS branchNm, h.ADDR AS addr, h.KEPCO_CUST_NO AS kepcoCustNo, h.RESULT_TEXT AS resultText, h.ORAL_NOTICE_YN AS oralNoticeYn, h.FAIL_DETAIL AS failDetail, h.LINE_NO AS lineNo, h.CAPACITY AS capacity, h.CHECK_CYCLE AS checkCycle, h.CONTRACT_TYPE AS contractType, h.DEFECT_CNT AS defectCnt, h.MOTOR_TYPE AS motorType, TO_CHAR(h.CHECK_DT, 'YYYY-MM-DD') AS checkDt, h.HIST_SEQ AS histSeq FROM ( SELECT 'GENERAL' AS FACILITY_TYPE, g.BRANCH_NM, g.ADDR, g.KEPCO_CUST_NO, g.CHECK_RESULT AS RESULT_TEXT, g.ORAL_NOTICE_YN, g.NONCONFORMITY_DETAIL AS FAIL_DETAIL, g.LINE_NO, g.CAPACITY, g.CHECK_CYCLE, g.CONTRACT_TYPE, NULL AS DEFECT_CNT, NULL AS MOTOR_TYPE, g.CHECK_DT, g.HIST_SEQ, ROW_NUMBER() OVER ( PARTITION BY g.BLDG_SEQ, COALESCE(g.KEPCO_CUST_NO, '__NULL__') ORDER BY g.CHECK_DT DESC, g.REG_DT DESC, g.HIST_SEQ DESC ) AS RN FROM TB_FACILITY_GENERAL_HIST g WHERE g.BLDG_SEQ = #{bldgSeq}
UNION ALL
SELECT 'SELF' AS FACILITY_TYPE, s.BRANCH_NM, s.ADDR, s.KEPCO_CUST_NO, s.INSPECTION_RESULT AS RESULT_TEXT, NULL AS ORAL_NOTICE_YN, s.FAIL_DETAIL AS FAIL_DETAIL, NULL AS LINE_NO, NULL AS CAPACITY, NULL AS CHECK_CYCLE, NULL AS CONTRACT_TYPE, s.DEFECT_CNT AS DEFECT_CNT, s.MOTOR_TYPE AS MOTOR_TYPE, s.CHECK_DT, s.HIST_SEQ, ROW_NUMBER() OVER ( PARTITION BY s.BLDG_SEQ, COALESCE(s.KEPCO_CUST_NO, '__NULL__') ORDER BY s.CHECK_DT DESC, s.REG_DT DESC, s.HIST_SEQ DESC ) AS RN FROM TB_FACILITY_SELF_HIST s WHERE s.BLDG_SEQ = #{bldgSeq} ) h WHERE h.RN = 1 ORDER BY CASE WHEN h.FACILITY_TYPE = 'GENERAL' THEN 1 ELSE 2 END, h.CHECK_DT DESC, h.KEPCO_CUST_NO



    AND v.COMBINED_RISK_CD IN ('D', 'E')

        AND () = #{hqNm}


        AND () = #{branchNm}


        AND v.REGION_NM = #{regionNm}


        AND v.DISTRICT_NM = #{districtNm}


ORDER BY v.COMBINED_SCORE DESC

SELECT q.* FROM ( SELECT v.BLDG_SEQ AS bldgSeq, AS branchNm, v.REGION_NM AS regionNm, v.DISTRICT_NM AS districtNm, v.REGION_CD AS regionCd, v.A13 AS bldgNm, AS addr, v.LON AS lon, v.LAT AS lat, v.TOTAL_SCORE AS baseScore, v.TOTAL_GRADE AS baseGrade, v.RISK_CD AS baseRiskCd, v.COMBINED_SCORE AS totalScore, v.COMBINED_SCORE AS combinedScore, v.COMBINED_GRADE_NM AS totalGrade, v.COMBINED_GRADE_NM AS combinedGradeNm, v.COMBINED_RISK_CD AS riskCd, v.COMBINED_RISK_CD AS combinedRiskCd, COUNT(*) OVER() AS totalMatchedCount FROM VW_RISK_COMBINED v WHERE
AND v.COMBINED_RISK_CD IN
#{riskCd}
AND v.LON >= #{minLon}
AND v.LAT >= #{minLat}
AND v.LON <= #{maxLon}
AND v.LAT <= #{maxLat}
) q ORDER BY q.totalScore DESC
OFFSET 0 ROWS FETCH NEXT #{maxRows} ROWS ONLY
